(function(){
'use strict';
const D=PAY_DATA,M=MODEL_DATA,E=PayEngine,B=PayBenchmarks,PL=PayLayers,$=id=>document.getElementById(id);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=x=>new Intl.NumberFormat('en-US',{maximumFractionDigits:0}).format(x);
const money=(x,c='US')=>x===null||!Number.isFinite(x)?'—':`${x<0?'−':''}${c==='CA'?'CA':'US'}$${n(Math.abs(x))}`;
const intl=x=>`I$ ${n(x)}`;
const states=Object.keys(D.rpp).filter(x=>x!=='United States').sort();
const postal=Object.fromEntries('Alabama:AL|Alaska:AK|Arizona:AZ|Arkansas:AR|California:CA|Colorado:CO|Connecticut:CT|Delaware:DE|District of Columbia:DC|Florida:FL|Georgia:GA|Hawaii:HI|Idaho:ID|Illinois:IL|Indiana:IN|Iowa:IA|Kansas:KS|Kentucky:KY|Louisiana:LA|Maine:ME|Maryland:MD|Massachusetts:MA|Michigan:MI|Minnesota:MN|Mississippi:MS|Missouri:MO|Montana:MT|Nebraska:NE|Nevada:NV|New Hampshire:NH|New Jersey:NJ|New Mexico:NM|New York:NY|North Carolina:NC|North Dakota:ND|Ohio:OH|Oklahoma:OK|Oregon:OR|Pennsylvania:PA|Rhode Island:RI|South Carolina:SC|South Dakota:SD|Tennessee:TN|Texas:TX|Utah:UT|Vermont:VT|Virginia:VA|Washington:WA|West Virginia:WV|Wisconsin:WI|Wyoming:WY'.split('|').map(x=>x.split(':')));
const blank=()=>({plan:PayPlanner.defaults(),country:'US',place:'Oklahoma',cityTax:'none',priceArea:'',kind:'employee',incomeMode:'custom',benchmarkBasis:'auto',gross:500000,overhead:0,liability:0,reimbursement:0,licence:0,tail:0,health:4440,healthPremium:1440,healthOutOfPocket:1000,disability:2000,professionalMode:'employer',costPreset:'single',costNote:'KFF worker premium average; other allowances are editable planning assumptions.',federalOverride:'',stateOverride:'',payrollOverride:'',localOverride:'',budget:'',extraNetCosts:0,priceOverride:'',referenceBasket:'',priceAdjustment:0,specialty:'Family medicine',source:'Entered scenario; not a measured physician salary.'});
let scenarios=[],compareMode='local',lifestyle=5000,stress=15,period=1;
function options(list,value){return list.map(x=>{const [v,label]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}"${String(v)===String(value)?' selected':''}>${esc(label)}</option>`;}).join('');}
function select(i,key,label,list,value,cls=''){return `<label class="${cls}">${label}<select data-side="${i}" data-key="${key}">${options(list,value)}</select></label>`;}
function input(i,key,label,value,help='',max=10000000,min=0){return `<label>${label}<input type="number" inputmode="decimal" min="${min}" max="${max}" step="any" data-side="${i}" data-key="${key}" value="${esc(value)}"${value===''?' placeholder="Use model"':''}>${help?`<span class="hint">${help}</span>`:''}</label>`;}
const link=(url,label)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label}</a>`;
const src={kff:M.sources[0][1],cmpa:M.sources[1][1],ama:M.sources[2][1],population:M.sources[3][1],mbm:D.sources.find(x=>x[0].startsWith('Statistics Canada local'))[1],bea:D.sources.find(x=>x[0].startsWith('BEA regional'))[1],ppp:D.sources.find(x=>x[0].startsWith('World Bank'))[1]};
function availablePrices(s){if(s.country==='CA')return D.mbm.filter(m=>m.province===s.place).map(m=>[m.name,m.name]);return [['','State-wide prices'],...D.metro.filter(m=>m.name.split(', ').at(-1).split('-').includes(postal[s.place])).map(m=>[m.name,m.name])];}
function ensurePrice(s){const list=availablePrices(s);if(!list.some(x=>x[0]===s.priceArea))s.priceArea=s.country==='CA'?M.anchors.find(x=>x.province===s.place).area:'';}
function syncHealth(s){s.health=Number(s.healthPremium)+Number(s.healthOutOfPocket)+Number(s.disability);}
function applyCosts(s,preset='single'){
 s.costPreset=preset;const family=preset==='family',ca=s.country==='CA',business=s.kind==='business';
 s.professionalMode=business?'included':'employer';s.licence=ca?2500:1500;s.tail=0;s.reimbursement=0;
 s.liability=ca?(E.cmpa(s)?.fee??0):/obstetric/i.test(s.specialty)?100000:/surgery/i.test(s.specialty)?50000:15000;
 s.healthPremium=ca?(family?3000:1500):(business?(family?M.health.usFullFamily:M.health.usFullSingle):(family?M.health.usWorkerFamily:M.health.usWorkerSingle));
 s.healthOutOfPocket=ca?(family?1500:750):(family?2500:1000);s.disability=2000;syncHealth(s);
 const historical=M.overheads.find(x=>x.specialty===s.specialty);
 if(business)s.overhead=ca?(historical?.historical_overhead_percent??30):45;else s.overhead=0;
 s.costNote=ca?'Supplemental health, out-of-pocket, disability and dues amounts are planning allowances, not measured averages.':'Health premium uses the KFF 2025 national group-plan survey. Out-of-pocket, disability, dues and self-paid liability budgets are planning assumptions.';
}
function resetPreset(name){compareMode='local';period=1;stress=15;lifestyle=5000;
 if(name==='median'){scenarios=[{...blank(),country:'CA',place:'BC',priceArea:'Vancouver, British Columbia'},blank()];scenarios.forEach(s=>{B.apply(s);applyCosts(s);});return;}
 if(name==='nyok'){scenarios=[{...blank(),place:'New York',cityTax:'nyc',priceArea:'New York-Newark-Jersey City, NY-NJ'},blank()];scenarios.forEach(s=>applyCosts(s));}
 else if(name==='derm'){scenarios=['AB','ON'].map(p=>{const s={...blank(),country:'CA',place:p,kind:'business',priceArea:p==='AB'?'Calgary, Alberta':'Toronto, Ontario',specialty:'Dermatology',gross:Math.round(D.ca.find(r=>r.province===p&&r.specialty==='Dermatology').median),source:'CIHI 2023–24 gross clinical median. Different workloads included; Ontario underreported. Not an attending salary offer.'};B.apply(s);applyCosts(s);return s;});}
 else{scenarios=[{...blank(),country:'CA',place:'BC',priceArea:'Vancouver, British Columbia',kind:'net',gross:208000,source:'Illustrative entered take-home: CA$208,000, with tax and professional costs already deducted.'},{...blank(),kind:'net',gross:316000,source:'Illustrative entered take-home: US$316,000, with tax and professional costs already deducted.'}];}
}
function renderScenario(i){const s=scenarios[i];ensurePrice(s);const ca=s.country==='CA',direct=s.kind==='net',business=s.kind==='business',c=ca?'CAD':'USD';const specs=B.specialties(s.country);
 const r=estimate(s),manual=!r.valid&&!direct&&Number(s.gross)>0;
 return `<article class="scenario" id="side-${i}"><div class="scenario-top"><div class="scenario-name"><span class="letter">${i?'B':'A'}</span><h3>${esc(ca?D.provinces[s.place]:s.place)}</h3><span class="currency">${c}</span></div><div class="grid2">
 ${select(i,'country','Country',[['US','United States'],['CA','Canada']],s.country)}${select(i,'place',ca?'Province':'State / DC',ca?Object.entries(D.provinces):states,s.place)}
 ${select(i,'priceArea',ca?'Local cost area · select where you would live':'Local cost area',availablePrices(s),s.priceArea,'full')}
 ${select(i,'incomeMode','Income source',[['benchmark','Published median · automatic'],['custom','Enter my own income']],s.incomeMode,'full')}
 ${s.incomeMode!=='benchmark'?select(i,'kind','Start with',[['net','I already know my take-home'],['employee','An employee salary, before tax'],['business','Practice revenue, before expenses']],s.kind,'full'):''}
 ${s.incomeMode==='benchmark'?benchmarkCard(s):input(i,'gross',`${direct?'Annual take-home':business?'Annual practice revenue':'Annual salary'} (${c})`,s.gross,direct?'After tax, practice and insurance costs; before household spending.':'Use an offer or the clearly labeled specialty benchmark.')}
 ${direct?input(i,'extraNetCosts','Costs still to deduct / year',s.extraNetCosts,'Only expenses NOT already deducted from your take-home.'):business?input(i,'overhead','All practice overhead (%)',s.overhead,'Includes professional costs unless you select separate itemization below.',95):`<div class="explain"><strong>Employer pays practice overhead.</strong><span>Rent, staff and billing costs are not deducted again from an employee salary.</span></div>`}
 </div><p class="source-note" id="source-${i}">${esc(s.source)}</p>
 ${direct?`<div class="notice neutral">No taxes or insurance are deducted again. Switch “Start with” to salary or practice revenue to model those costs.</div>`:`<details><summary>Benchmark source & specialty</summary><div class="grid2">${select(i,'specialty','Specialty',specs,s.specialty,'full')}${!ca?select(i,'benchmarkBasis','Published median source',[['auto','Medical-group median; state wages if unavailable'],['national','AMGA national compensation median only'],['state','BLS state wage median · mixed career stages']],s.benchmarkBasis,'full'):''}</div><p class="hint">Changes load the median automatically and clear fixed tax overrides when published-median mode is selected. <a href="#evidence">Inspect all pay evidence</a>.</p></details>${costForm(i)}
 <details${manual?' open':''}><summary>Tax settings ${manual?'· input needed':'· 2025 single filer'}</summary><p class="hint">Under 65, full-year resident. Overrides replace whole annual tax lines. “Family” health insurance does not change filing status. Use entered take-home for household, corporation or unsupported tax cases.</p><div class="grid2">
 ${!ca&&s.place==='New York'?select(i,'cityTax','Local income tax',[['nyc','NYC resident'],['none','Outside NYC (check other local taxes)']],s.cityTax,'full'):''}
 ${input(i,'federalOverride','Federal tax override',s.federalOverride)}${input(i,'stateOverride',ca?'Provincial tax override':'State tax override',s.stateOverride)}
 ${input(i,'payrollOverride','All payroll / social contributions',s.payrollOverride)}${input(i,'localOverride','Local / other tax override',s.localOverride)}
 </div><p class="hint">Quebec and unmodeled U.S. states require entered totals. Some modeled states also need local taxes. Enter 0 only when no tax applies. <a href="#tax-scope">See automatic tax coverage</a>.</p></details>`}
 <details><summary>Personalize prices & household budget</summary><p class="hint">The default reflects ${ca?'a modeled basic-basket price difference':'BEA average consumer prices'}. Housing quality, childcare and neighbourhood choice can change your costs.</p><div class="grid2">
 ${input(i,'priceAdjustment','Your costs above / below local index (%)',s.priceAdjustment,'For example +20 for a costlier lifestyle; −10 for lower local costs.',500,-90)}${input(i,'priceOverride','Override local relative price index',s.priceOverride,ca?'100 = modeled Canadian reference, before PPP.':'100 = U.S. average prices.',1000,1)}
 ${ca?input(i,'referenceBasket','Canadian reference basket override (CAD)',s.referenceBasket,`Default ${n(M.referenceBasket)}: province-population-weighted city proxy. See method.`,200000,10000):''}
 ${input(i,'budget',`Your monthly living budget (${c})`,s.budget,'Optional actual budget for the same household and lifestyle. Exclude insurance already deducted.')}
 </div></details>
 </div><div class="result" id="result-${i}"></div></article>`;
}
function costForm(i){const s=scenarios[i],ca=s.country==='CA',business=s.kind==='business',covered=s.professionalMode!=='separate',fee=ca?E.cmpa(s):null;const h=M.overheads.find(x=>x.specialty===s.specialty);
 return `<details class="costs" open><summary>Practice, insurance & professional costs</summary><div class="grid2">${select(i,'costPreset','Expense defaults',[['single','Single-person health coverage'],['family','Family health coverage'],['custom','Custom amounts']],s.costPreset,'full')}${select(i,'professionalMode','Malpractice / CMPA, dues and tail are…',business?[['included','Included in my overhead percentage'],['separate','Separate from my overhead percentage']]:[['employer','Paid by my employer'],['separate','Paid by me']],s.professionalMode,'full')}</div>
 <p class="cost-status">${covered?business?'Included once in practice overhead. No second deduction.':'Employer-paid by assumption. Your contract must confirm coverage.':'Your unreimbursed professional costs are deducted below.'}</p>
 ${business?`<p class="hint">${ca?`Overhead starting point: ${h?`${h.historical_overhead_percent}% from a historical 2017 CMA profile`:'30% planning allowance'}. ${h?.specialty==='Dermatology'?'The 35% figure describes medical specialists broadly. ':''}This is an old national reference, not current provincial expense data.`:'45% all-in overhead is an editable planning assumption, not a measured U.S. or state average.'}</p>`:''}
 ${!covered?`<div class="grid2">${input(i,'liability',ca?'CMPA gross annual fee':'Malpractice premium / year',s.liability,ca?'2025 published fee when loaded. Confirm work type.':'Planning allowance until replaced with an insurer quote.')}${input(i,'reimbursement','Reimbursement received / year',s.reimbursement,'0 means none assumed; check your employer/province.')}${input(i,'licence','Licensing & professional dues',s.licence,'Planning allowance; replace with your annual net cost.')}${input(i,'tail','Tail coverage paid this year',s.tail,'0 assumes no tail payment this year. Confirm contract.')}</div>`:''}
 ${ca&&fee?`<p class="hint">Published CMPA reference: <strong>${money(fee.fee,'CA')} / year</strong>, work code ${fee.code}, before any provincial reimbursement${s.place==='QC'?' (Québec tax included)':''}. ${link(src.cmpa,'2025 fee schedule')}. ${covered?'Shown for context; already covered by the selected cost arrangement.':'<button class="text-button" data-cmpa="'+i+'">Load this fee</button>'}</p>`:''}
 ${!ca?`<p class="hint">A single state-wide malpractice average would be misleading. In the AMA’s 2025 selected-insurer examples, internal-medicine manual premiums were ${money(8274)} in LA/Orange counties and ${money(59736)} in Miami-Dade. These are quoted rate examples, not state averages. ${link(src.ama,'AMA, Exhibit 4')}.</p>`:''}
 <div class="grid2">${input(i,'healthPremium',ca?'Supplemental health / dental premium':'Your health-plan premium / year',s.healthPremium,ca?'Editable planning allowance.':`${business?'Full group-plan premium proxy':'Worker contribution average'}; ${link(src.kff,'KFF 2025')}.`)}${input(i,'healthOutOfPocket','Expected out-of-pocket health care',s.healthOutOfPocket,'Planning reserve; not a deductible charged automatically.')}${input(i,'disability','Disability / other personal insurance',s.disability,'Planning allowance; actual own-occupation premiums vary.')}</div>
 <p class="hint">${esc(s.costNote)} Health costs are subtracted after tax here; pretax benefits or tax deductions require overrides. No insurance allowance is an individual quote.</p></details>`;
}
function benchmarkCard(s){const b=B.get(s);return `<div class="benchmark-card full ${b.quality==='broad-state-wage'||b.value===null?'limited':''}"><span class="benchmark-badge">${esc(b.badge)}</span><div class="benchmark-value">${b.value===null?'Not published':money(Math.round(b.value),s.country)}</div><div class="hint">${esc(b.scope)} · ${esc(b.year)} · ${b.kind==='business'?'before expenses and tax':'before personal tax'}</div><p class="benchmark-note">${esc(b.note)}</p>${b.range?`<p class="hint">40th–60th percentile gross payments: ${money(b.range[0],'CA')}–${money(b.range[1],'CA')}. This is a distribution band, not a full-time salary range.</p>`:''}${link(b.url,'Published source')} · <a href="#evidence">Pay evidence</a></div>`;}
function estimate(s){if(s.incomeMode==='benchmark'&&B.get(s).value===null)return {valid:false,missing:[B.get(s).note],warnings:[],gross:null,practice:null,personal:null,cash:null};return E.calc(s);}
function renderQuick(){return scenarios.map((s,i)=>{const ca=s.country==='CA',direct=s.kind==='net',benchmark=s.incomeMode==='benchmark';return `<div class="quick-side"><div class="scenario-name"><span class="letter">${i?'B':'A'}</span><h3>${ca?'Canada':'United States'}</h3><span class="currency">${ca?'CAD':'USD'}</span></div><div class="grid2">${select(i,'country','Country',[['US','United States'],['CA','Canada']],s.country)}${select(i,'place',ca?'Province':'State / DC',ca?Object.entries(D.provinces):states,s.place)}${select(i,'specialty','Specialty',B.specialties(s.country),s.specialty,'full')}${select(i,'incomeMode','Income source',[['benchmark','Published median · automatic'],['custom','Enter my own income']],s.incomeMode,'full')}${benchmark?benchmarkCard(s):select(i,'kind','Income type',[['net','Known take-home'],['employee','Employee salary'],['business','Practice revenue']],s.kind)+input(i,'gross',`Annual ${direct?'take-home':s.kind==='business'?'revenue':'salary'} (${ca?'CAD':'USD'})`,s.gross)}${select(i,'priceArea','Local cost area',availablePrices(s),s.priceArea,'full')}${!ca&&s.place==='New York'&&!direct?select(i,'cityTax','Tax residence (separate from price area)',[['nyc','NYC resident'],['none','Outside NYC; check other local taxes']],s.cityTax,'full'):''}</div><p id="quick-result-${i}" class="quick-result"></p><p class="hint">${!benchmark&&direct?'Entered cash should already account for tax, professional and insurance costs.':'Expenses and tax assumptions are editable below.'} <a href="#side-${i}">${direct?'Additional costs and budget':'Review expenses and taxes'}</a>.</p></div>`;}).join('');}
function renderForms(){ PL.renderForms();$('scenarios').innerHTML=scenarios.map((s,i)=>renderScenario(i)).join('');$('quick-controls').innerHTML=renderQuick();renderResults();}
function renderResult(i,r){const s=scenarios[i],c=s.country,direct=s.kind==='net';const row=(name,v,help='')=>`<div><dt>${name}${help?`<small>${help}</small>`:''}</dt><dd>${money(v,c)}</dd></div>`;
 $('result-'+i).innerHTML=`<div class="cash-label">${r.valid?'ANNUAL CASH BEFORE HOUSEHOLD SPENDING':'INCOME / TAX INPUT NEEDED'}</div><div class="cash">${r.valid?money(r.cash,c):'Estimate incomplete'}</div><div class="monthly">${r.valid?`${money(r.cash/12,c)} per month`: 'Select a usable benchmark, enter your income, or fill the required tax totals.'}</div>
 ${r.missing.length?`<div class="notice"><ul>${r.missing.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}
 <details class="ledger-details"${direct?'':' open'}><summary>${direct?'How entered cash is treated':'Follow the money'}</summary><dl class="ledger">
 ${direct?row('Entered take-home',r.gross,'Taxes and insurance already accounted for')+row('Additional costs you entered',r.personal):row(s.kind==='business'?'Practice revenue':'Employee salary',r.gross)+row('Practice costs deducted',r.practice,s.kind==='employee'?'Employer operating costs are upstream of salary':s.professionalMode==='included'?'Includes professional costs; not counted twice':'Overhead plus separate unreimbursed professional costs')+row('Federal income tax',r.federal)+row(c==='CA'?'Provincial income tax':'State income tax',r.state)+row('Local / other tax',r.local)+row(c==='CA'?'CPP/QPP + EI/QPIP':'Payroll / social contributions',r.payroll)+row('Personal insurance / professional costs',r.personal)}
 ${r.valid?`<div class="total"><dt>Cash available</dt><dd>${money(r.cash,c)}</dd></div>`:''}</dl></details>
 ${r.valid&&Number(s.budget)>0?`<p class="budget-note">After your entered living budget: <strong>${money(r.cash/12-Number(s.budget),c)} / month</strong>.</p>`:''}
 <details><summary>Calculation limits</summary>${r.warnings.map(w=>`<p class="hint">${esc(w)}</p>`).join('')}</details>`;
}
function renderResults(){const results=scenarios.map(s=>estimate(s));results.forEach((r,i)=>{renderResult(i,r);const el=$('quick-result-'+i);if(el)el.textContent=r.valid?`Cash after modeled taxes and costs: ${money(r.cash,scenarios[i].country)} / year`:'Choose an available median or complete the income/tax inputs below.';});renderComparison(results);PL.renderResults();}
function renderComparison(results){const powers=scenarios.map((s,i)=>E.commonPower(s,results[i])),valid=results.every(r=>r.valid)&&powers.every(Boolean);
 const controls=`<div class="compare-controls"><label>Comparison measure<select id="compare-mode">${options([['local','Local purchasing power · modeled'],['national','National purchasing power only'],['budget','My entered household budgets']],compareMode)}</select></label><label>Show amounts<select id="period">${options([[1,'Per year'],[12,'Per month']],period)}</select></label></div>`;
 if(!valid){$('comparison').innerHTML=`<div class="section-head"><div><h2>Purchasing power comparison</h2><p>Every Canadian province and U.S. state can be compared.</p></div>${controls}</div><div class="notice">${results.some(r=>!r.valid)?'Select a published numeric median or enter your own income; complete any required tax inputs below.':'Enter a valid local price index and cost adjustment in both scenarios.'}</div>`;bindCompare();return;}
 const budgets=scenarios.map(s=>Number(s.budget));
 if(compareMode==='budget'&&budgets.some(x=>!Number.isFinite(x)||x<=0)){$('comparison').innerHTML=`<div class="section-head"><div><h2>Compare the same household lifestyle</h2><p>Enter a monthly living budget in both scenarios under “Personalize prices & household budget.” Use equivalent housing, transport and household needs.</p></div>${controls}</div>`;bindCompare();return;}
 const values=results.map((r,i)=>compareMode==='budget'?r.cash/(budgets[i]*12):compareMode==='national'?powers[i].national:powers[i].value),max=Math.max(1,...values),ratio=values[0]>0?values[1]/values[0]:null;
 const units=compareMode==='budget'?budgets.map(x=>x*12):compareMode==='national'?powers.map(p=>p.ppp):powers.map(p=>p.unit);
 const names=scenarios.map(s=>s.country==='CA'?D.provinces[s.place]:s.place),annual=period===1;
 const format=x=>compareMode==='budget'?`${x.toFixed(2)}×`:intl(x/period);
 const positive=values.every(v=>v>0),winner=values[1]>values[0]?1:0,loser=1-winner;
 const headline=positive?`${names[winner]}: ${(values[winner]/values[loser]).toFixed(1)}× the ${compareMode==='budget'?'budget coverage':'purchasing power'}`:'Compare the cash available for spending';
 const explanation=compareMode==='local'?'Both locations are now expressed in the same purchasing-power unit. This includes currency price levels and local cost differences.':compareMode==='national'?'Currency price levels are included; local cost differences are excluded. I$ means spending power at U.S.-average prices, not currency received.':'Each cash income is divided by that location’s annual budget. The budgets must describe the same household lifestyle.';
 const required=values[winner]*units[loser],stressFactor=stress/100;
 $('comparison').innerHTML=`<div class="section-head"><div><p class="eyebrow">${compareMode==='local'?'THE SAME MONEY BUYS DIFFERENT AMOUNTS':'YOUR COMPARISON'}</p><h2>${esc(headline)}</h2></div>${controls}</div><p>${explanation}</p>${scenarios.some(s=>s.incomeMode==='benchmark')?'<p class="benchmark-comparison-note">Benchmark populations differ. Canadian gross payments, national medical-group compensation and broader state wages are not a controlled comparison of full-time attending pay. Review the source labels above.</p>':''}
 <div class="compare-grid">${powers.map((p,i)=>`<div class="power-card"><div class="compare-label"><span class="letter">${i?'B':'A'}</span> ${esc(names[i])}</div><div class="power">${format(values[i])}</div><div class="compare-label">${compareMode==='budget'?'annual household budgets covered':`of ${annual?'annual':'monthly'} spending at U.S.-average prices`}</div><div class="power-bar" aria-hidden="true"><span style="width:${Math.max(0,values[i]/max*100)}%"></span></div><div class="compare-label">Actual cash: <strong>${money(results[i].cash/period,scenarios[i].country)}</strong> / ${annual?'year':'month'}</div><p class="hint">${esc(p.area)}${scenarios[i].country==='CA'?' · Canadian local-price proxy':''}</p></div>`).join('')}</div>
 ${positive?`<p class="match">To match ${esc(names[winner])}’s ${compareMode==='budget'?'budget coverage':'spending power'}, you would need <strong>${money(required,scenarios[loser].country)} a year after tax and professional costs in ${esc(names[loser])}</strong>. That is ${money(required-results[loser].cash,scenarios[loser].country)} more than the entered take-home.</p>`:''}
 ${compareMode==='local'?`<div class="model-note"><strong>Modeled comparison, not an official city-to-city PPP.</strong> U.S. prices: BEA 2024. Canada: World Bank 2024 consumption PPP × a local basic-basket adjustment. I$1 means the purchasing power of US$1 at average U.S. prices—not a bank exchange rate. ${link(src.bea,'BEA')} · ${link(src.ppp,'World Bank')} · ${link(src.mbm,'Statistics Canada')}.</div>
 <details><summary>See the currency and local-price calculation</summary><div class="table-wrap"><table><thead><tr><th>Step · annual values</th><th>A</th><th>B</th></tr></thead><tbody>
 <tr><td>Spendable cash, local currency</td>${results.map((r,i)=>`<td>${money(r.cash,scenarios[i].country)}</td>`).join('')}</tr>
 <tr><td>National consumption PPP (local currency / I$)</td>${powers.map(p=>`<td>${p.ppp.toFixed(4)}</td>`).join('')}</tr>
 <tr><td>Local price factor × personal adjustment</td>${powers.map(p=>`<td>${p.factor.toFixed(3)} × ${(1+p.adjustment/100).toFixed(3)}</td>`).join('')}</tr>
 <tr><td>Local currency needed to buy I$1</td>${powers.map(p=>`<td>${p.unit.toFixed(3)}</td>`).join('')}</tr>
 <tr><td>Cash ÷ local currency per I$</td>${powers.map(p=>`<td>${intl(p.value)}</td>`).join('')}</tr></tbody></table></div><p class="hint">Canadian reference in use: ${powers.map((p,i)=>scenarios[i].country==='CA'?`${i?'B':'A'} ${money(p.reference,'CA')}`:'').filter(Boolean).join('; ') || 'not applicable'} (modeled city proxy or your override). ${powers.some(p=>p.custom)?'A custom local index is active. ':''}<a href="#price-method">Inspect the calibration and limitations</a>.</p></details>
 <div class="sensitivity"><label>Stress-test each local cost estimate: ±${stress}%<input id="stress" type="range" min="0" max="30" step="5" value="${stress}"></label><p>With costs varied independently by this amount: ${powers.map((p,i)=>`${i?'B':'A'} = <strong>${intl(p.value/(1+stressFactor)/period)}–${intl(p.value/(1-stressFactor)/period)}</strong>`).join('; ')}. ${positive?`B/A spending-power ratio: <strong>${(ratio*(1-stressFactor)/(1+stressFactor)).toFixed(2)}–${(ratio*(1+stressFactor)/(1-stressFactor)).toFixed(2)}×</strong>.`:''}</p><p class="hint">An analyst-chosen sensitivity test, not a confidence interval. It does not capture every tax, pay or lifestyle uncertainty.</p></div>`:''}
 <div class="lifestyle"><h3>${compareMode==='budget'?'Cash left after your budgets':'What could a comparable lifestyle cost?'}</h3>${compareMode!=='budget'?`<label>Illustrative monthly lifestyle at U.S.-average prices (I$)<input id="lifestyle" type="number" min="0" max="1000000" value="${lifestyle}"></label><p class="hint">${compareMode==='national'?'Uses national prices only. ':''}An editable spending target, not an observed physician household budget. Housing, food, transport and other living expenses; exclude insurance already deducted. Use “My entered household budgets” for actual local estimates.</p>`:''}
 <div class="compare-grid">${results.map((r,i)=>{const monthly=compareMode==='budget'?budgets[i]:lifestyle*units[i];return `<div><div class="compare-label">${i?'B':'A'} · ${esc(names[i])}</div><dl class="ledger">${`<div><dt>Monthly living costs</dt><dd>${money(monthly,scenarios[i].country)}</dd></div><div><dt>Cash left each month</dt><dd>${money(r.cash/12-monthly,scenarios[i].country)}</dd></div>`}</dl></div>`;}).join('')}</div><p class="hint">Cash left is in local currency. It is not converted into extra savings using PPP. Purchasing a home, repaying debt or investing abroad needs its own budget and exchange-rate analysis.</p></div>`;
 bindCompare();
}
function bindCompare(){ $('compare-mode')?.addEventListener('change',e=>{compareMode=e.target.value;renderResults();});$('period')?.addEventListener('change',e=>{period=Number(e.target.value);renderResults();});$('stress')?.addEventListener('change',e=>{stress=Number(e.target.value);renderResults();});$('lifestyle')?.addEventListener('change',e=>{const v=Number(e.target.value);if(Number.isFinite(v)&&v>=0&&v<=1000000)lifestyle=v;renderResults();});}
function setBenchmark(i){const s=scenarios[i];B.apply(s);applyCosts(s,s.costPreset==='family'?'family':'single');renderForms();}
function formatEvidence(x,c){if(x===null||x===undefined||x==='')return 'Not published';if(x==='#')return 'At least $239,200';if(x==='*'||x==='**')return 'Unavailable / suppressed';let val=Number(String(x).replaceAll(',',''));return Number.isFinite(val)?money(val,c):esc(x);}
function renderEvidence(reset=false){const country=$('evidence-country').value;const place=$('evidence-place');if(reset){place.innerHTML=options(country==='CA'?Object.entries(D.provinces):country==='US'?states:[['National','National medical groups']],country==='CA'?'AB':country==='US'?'New York':'National');}
 const search=$('evidence-search').value.toLowerCase();let rows=[],head=[];
 if(country==='CA'){
  $('evidence-note').textContent='Observed gross clinical payments, CAD, 2023–24. These are not net income or full-time-only pay. Ontario is underreported; PEI includes short-term/locum payees; Saskatchewan total-clinical medians are unavailable. Internal medicine includes subspecialties and overlaps other rows. Imaging/laboratory specialties are not covered.';
  rows=D.ca.filter(r=>r.province===place.value&&r.specialty.toLowerCase().includes(search)).map(r=>[r.specialty,formatEvidence(r.median,'CA'),formatEvidence(r.p40,'CA'),formatEvidence(r.p60,'CA'),String(r.n??'Unavailable')]);head=['Specialty','Gross median','40th percentile','60th percentile','Payees'];
 }else if(country==='US'){
  $('evidence-note').textContent='BLS May 2025 annual wage rates, USD. Includes trainees and mixed career stages; excludes self-employed physicians and some compensation. These are not attending-only salary predictions. A lower bound is not a measured median; missing data are not zero.';
  rows=D.us.filter(r=>r.state===place.value&&r.specialty.toLowerCase().includes(search)).map(r=>[r.specialty,formatEvidence(r.median,'US'),formatEvidence(r.p25,'US'),formatEvidence(r.p75,'US')]);head=['Occupation','Wage median','25th percentile','75th percentile'];
 }else{
  $('evidence-note').textContent='AMGA 2025 survey of 2024 compensation, USD. Employer-reported participating medical-group medians. These are national benchmarks, not measured state medians or guaranteed offers. No geographic multipliers are invented.';
  rows=D.amga.filter(r=>r[0].toLowerCase().includes(search)).map(r=>[r[0],money(r[1]),'National participating medical groups']);head=['Specialty / setting','Compensation median','Scope'];
 }
 $('evidence-head').innerHTML='<tr>'+head.map(h=>`<th scope="col">${h}</th>`).join('')+'</tr>';
 $('evidence-body').innerHTML=rows.length?rows.map(r=>'<tr>'+r.map((c,j)=>`<td${j?' class="number"':''}>${esc(c)}</td>`).join('')+'</tr>').join(''):`<tr><td colspan="5">No matching specialties.</td></tr>`;
}
function method(){const total=M.anchors.reduce((t,x)=>t+x.population,0);
 $('method-content').innerHTML=`<div class="method-grid">
 <article><h3>1. Identify the kind of income</h3><p>Employee salary is already downstream of the employer’s rent, staff, billing and other operating expenses. Practice revenue is the money collected before those expenses. Entering a known take-home bypasses the tax model and assumes tax, practice and insurance costs are already accounted for.</p><p>Salary evidence remains separate from hypothetical offers. Canadian CIHI gross medians include mixed workloads; U.S. BLS wage data are not attending-only. The AMGA medians describe participating medical groups nationally. The default selects a CIHI provincial gross median in Canada. In the U.S. it prefers an AMGA national compensation median; if absent, it uses a published numeric BLS state wage median with a prominent mixed-workforce label. Missing or top-coded values clear the income. No invented specialty-by-state pay multipliers are applied. <a href="#evidence">Pay evidence and limitations</a>.</p></article>
 <article><h3>2. Calculate cash you can spend</h3><p>Revenue or salary − practice costs − income taxes − payroll contributions − personal insurance/professional expenses. Business professional costs reduce taxable profit only when itemized separately from overhead. Employee personal costs are deducted after tax. “Included in overhead” and “employer-paid” both prevent a second professional-cost deduction.</p><p>Living costs come later. The main purchasing-power result adjusts all spendable cash for prices; the separate lifestyle panel subtracts a budget to show cash remaining. The two calculations are not stacked on top of one another.</p></article>
 <article id="price-method"><h3>3. Put every place in one purchasing-power unit</h3><p><strong>U.S. local currency per I$ = BEA regional price parity ÷ 100.</strong> <strong>Canadian local currency per I$ = ${D.ppp} × local MBM basket ÷ ${M.referenceBasket.toFixed(2)}.</strong> Then divide cash by that local-currency cost. A personal cost adjustment multiplies the local price factor.</p><p>World Bank private-consumption PPP bridges national price levels; BEA measures U.S. regional consumer prices. Canada’s MBM adds a modeled local adjustment. This multiplication is an analytical bridge, not an official Canada–U.S. city price index. All price inputs are 2024. ${link(src.ppp,'World Bank')} · ${link(src.bea,'BEA')} · ${link(src.mbm,'Statistics Canada')}.</p></article>
 <article><h3>4. Understand the Canadian calibration</h3><p>The reference is a province-population-weighted mean of one named city basket in each of the ten provinces. Provincial July 2024 populations weight the selected city costs. It assumes that these cities represent their provinces for this normalization; they are not measured provincial average prices. Territories are excluded.</p><p>The MBM prices a modest reference family basket. Its housing, geography and spending weights differ from national consumption PPP and from a physician household. This can bias the local adjustment. Use the sensitivity control and your own comparable local budgets, especially for home ownership, children or a costly neighbourhood. ${link(src.population,'Population weights')} · ${link(src.mbm,'MBM thresholds')}.</p></article>
 <article><h3>5. Use insurance defaults for what they are</h3><p>KFF’s 2025 employer survey reports annual worker premium contributions of US$1,440 for single coverage and US$6,850 for family coverage. Full premiums are US$9,325 and US$26,993. The employee presets use worker contributions; self-employed presets use full group premiums as a proxy, not an individual-market quote. These are general employer-plan averages, not physician averages. ${link(src.kff,'KFF 2025')}.</p><p>Supplemental Canadian coverage, out-of-pocket care, disability insurance and dues use labeled planning allowances. They are editable, not claimed survey averages. Health premiums are treated after tax; actual pretax benefits or deductions can increase take-home. Tail is zero only under the assumption that no tail bill is due this year.</p></article>
 <article><h3>6. Treat liability costs as location- and work-dependent</h3><p>Canadian physicians incur medical-liability protection costs too. The calculator includes CMPA’s 2025 regional fees for the listed work types; provincial reimbursements must be entered or included in overhead. Family medicine defaults to office work without obstetrics, anesthesia, ER shifts or surgery; broader work needs a different code. ${link(src.cmpa,'CMPA fee schedule')}.</p><p>U.S. malpractice varies too much for one reliable national specialty/state default. The self-paid amounts here—US$15,000 for medical work, US$50,000 for surgery and US$100,000 for obstetrics—are planning allowances, not measured averages or conservative bounds. Replace them with a local quote, including any patient-compensation-fund surcharge. Employer coverage is a contract assumption. ${link(src.ama,'AMA premium analysis')}.</p></article>
 <article id="tax-scope"><h3>Automatic tax coverage · fixed 2025 rules</h3><p>Canada: nine provinces, federal and provincial brackets, basic credits, CPP/CPP2, employee EI, Ontario surtax/health premium and Manitoba’s basic-amount phase-out. Quebec needs entered totals. U.S.: federal tax and Social Security/Medicare; state income tax in New York, Oklahoma, California, Arizona, Illinois, North Carolina, Virginia, Louisiana, Michigan, Kentucky and Colorado; and nine states without wage income tax. NYC resident tax, NY employee PFL, California employee SDI and Colorado employee FAMLI are included. Michigan/Kentucky/Colorado need local tax totals. Alaska/Washington need payroll overrides; remaining states need entered state, payroll and local totals.</p><p>Single, under 65, full-year residents only. Retirement deductions, dependants, itemized/SALT deductions, corporations, QBI, investment income and cross-border taxation are excluded. Full-year 2025 results are historical illustrations, not 2026 tax forecasts. A missing required tax input blocks the calculation. Enter known take-home to compare any location without relying on this tax scope.</p></article>
 <article><h3>What purchasing power does—and does not—mean</h3><p>I$ is a common consumption unit: spending power at average U.S. prices. It is not extra income, an exchange rate, or a promise about a particular house. A CA$ amount and a US$ amount must not be compared as if they were the same currency.</p><p>The ±15% default is an analyst-chosen stress test of each local price estimate, varied independently. It is not a statistical confidence interval or a bound on all errors. The selected-city Canadian calibration and mismatched baskets remain material limitations. Savings, overseas investing, debt and wealth accumulation require actual cash flows and exchange rates.</p></article>
 </div>
 <details><summary>Audit the Canadian reference · all ten population weights</summary><div class="table-wrap"><table><thead><tr><th>Province</th><th>City used for normalization</th><th>Population · July 2024</th><th>Weight</th><th>2024 basket · CAD</th></tr></thead><tbody>${M.anchors.map(a=>`<tr><td>${esc(D.provinces[a.province])}</td><td>${esc(a.area)}</td><td>${n(a.population)}</td><td>${(a.population/total*100).toFixed(2)}%</td><td>${money(a.basket,'CA')}</td></tr>`).join('')}<tr><td colspan="4"><strong>Weighted reference (model)</strong></td><td>${money(M.referenceBasket,'CA')}</td></tr></tbody></table></div><p class="hint">Σ(provincial population × selected city basket) ÷ Σ(provincial population). Changing the Canadian reference override changes cross-border calibration. It cancels in a Canada-only comparison when the same reference is used on both sides. Population estimates are the downloaded September 2026 vintage and can be revised.</p></details>
 <details><summary>Expense default amounts and provenance</summary><div class="table-wrap"><table><thead><tr><th>Expense</th><th>United States · single / family</th><th>Canada · single / family</th><th>Evidence type</th></tr></thead><tbody>
 <tr><td>Employee health premiums / year</td><td>US$1,440 / US$6,850</td><td>CA$1,500 / CA$3,000 supplemental</td><td>U.S.: KFF survey mean; Canada: planning allowance</td></tr>
 <tr><td>Self-employed health premiums / year</td><td>US$9,325 / US$26,993</td><td>CA$1,500 / CA$3,000 supplemental</td><td>U.S.: full group-plan proxy; Canada: allowance</td></tr>
 <tr><td>Out-of-pocket care / year</td><td>US$1,000 / US$2,500</td><td>CA$750 / CA$1,500</td><td>Planning reserve; not observed average spending</td></tr>
 <tr><td>Disability / other insurance</td><td>US$2,000</td><td>CA$2,000</td><td>Planning allowance</td></tr>
 <tr><td>Annual dues if self-paid</td><td>US$1,500</td><td>CA$2,500</td><td>Planning allowance, including annualized recurring licensing</td></tr>
 <tr><td>Practice overhead</td><td>45% of collections</td><td>Historical specialty profile; 30% fallback</td><td>U.S.: planning assumption; Canada: old 2017 CMA reference</td></tr>
 </tbody></table></div><p class="hint">Overhead is all-in by default. When choosing separate professional expenses, reduce the overhead percentage to exclude those same costs. Specialty benchmark or coverage-preset changes reload defaults; custom edits are marked as custom. Uniform health/dues allowances across states simplify planning without claiming identical actual costs.</p></details>
 <details><summary>Sources and data dates</summary><ul class="sources">${[...D.sources,...M.sources].map(([name,url])=>`<li>${link(esc(url),esc(name))}</li>`).join('')}</ul><p class="hint">Reviewed 9 September 2026. Pay: CIHI 2023–24; BLS May 2025; AMGA 2024 compensation. Tax and expense snapshot: 2025. Prices and population reference: 2024. Historical CMA overhead: 2017. No automatic inflation or salary forecast is added. Source datasets and calculation code ship with the download.</p></details>`;
}
document.addEventListener('input',event=>{const el=event.target;if(el.matches('input[data-side]')){const i=Number(el.dataset.side),s=scenarios[i],key=el.dataset.key;s[key]=el.value;
 document.querySelectorAll(`input[data-side="${i}"][data-key="${key}"]`).forEach(peer=>{if(peer!==el)peer.value=el.value;});
 if(key==='gross'){s.incomeMode='custom';s.source='Custom entered income; confirm amount and income type.';$('source-'+i).textContent=s.source;}
 if(['healthPremium','healthOutOfPocket','disability','liability','reimbursement','licence','tail','overhead'].includes(key)){s.costPreset='custom';const preset=document.querySelector(`select[data-side="${i}"][data-key="costPreset"]`);if(preset)preset.value='custom';}
 syncHealth(s);renderResults();}});
document.addEventListener('change',event=>{const el=event.target;if(!el.matches('select[data-side]'))return;const i=Number(el.dataset.side),s=scenarios[i],key=el.dataset.key;s[key]=el.value;
 const locationChange=key==='country'||key==='place';
 if(locationChange){
  if(key==='country')s.plan=PayPlanner.defaults();else{s.plan.budgetMode='modeled';s.plan.rent='';s.plan.housingArea='';s.plan.rentNote='Location changed. Choose a new local housing reference or enter a quote.';}
  if(key==='country'){s.place=s.country==='CA'?'BC':'Oklahoma';s.specialty=B.normalize(s.specialty,s.country);if(s.kind!=='net')s.kind=s.country==='CA'?'business':'employee';}
  s.priceArea='';s.cityTax='none';s.priceOverride='';s.priceAdjustment=0;s.referenceBasket='';
  for(const k of ['federalOverride','stateOverride','payrollOverride','localOverride','budget'])s[k]='';
  s.source='Location changed. Custom income is held fixed in the selected currency; confirm it for the new location.';
 }
 if(s.incomeMode==='benchmark'&&(locationChange||['specialty','incomeMode','benchmarkBasis'].includes(key))){B.apply(s);applyCosts(s,s.costPreset==='family'?'family':'single');for(const k of ['federalOverride','stateOverride','payrollOverride','localOverride'])s[k]='';}
 else if(s.kind!=='net'&&(locationChange||key==='kind'||key==='specialty'))applyCosts(s,s.costPreset==='family'?'family':'single');
 if(key==='incomeMode'&&s.incomeMode==='custom')s.source='Custom income mode. The previous number is kept as an editable starting point.';
 if(key==='kind'){s.incomeMode='custom';s.source='Income type changed. Check the amount: salary, revenue and take-home are different.';}
 if(key==='cityTax')s.localOverride='';
 if(key==='costPreset'&&s.costPreset!=='custom')applyCosts(s,s.costPreset);
 renderForms();
});
document.addEventListener('click',event=>{const target=event.target;
 const benchmark=target.closest('[data-benchmark]');if(benchmark){setBenchmark(Number(benchmark.dataset.benchmark));return;}
 const cmpa=target.closest('[data-cmpa]');if(cmpa){const s=scenarios[Number(cmpa.dataset.cmpa)];s.liability=E.cmpa(s).fee;s.costPreset='custom';renderForms();return;}
 const preset=target.closest('[data-preset]');if(preset){resetPreset(preset.dataset.preset);renderForms();return;}
 if(target.closest('#swap')){scenarios.reverse();renderForms();return;}
 if(target.closest('#export')){const payload={version:4,scenarios,compareMode,lifestyle,stress,period,layers:PL.settings()};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='physician-pay-comparison.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
});
$('import').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>100000)throw Error('File too large.');const v=JSON.parse(await file.text());if(![2,3,4].includes(v.version)||!Array.isArray(v.scenarios)||v.scenarios.length!==2)throw Error('Choose an exported Physician Pay comparison.');
 const next=v.scenarios.map(s=>{if(!['CA','US'].includes(s.country)||!(s.country==='CA'?Object.hasOwn(D.provinces,s.place):states.includes(s.place))||!['employee','business','net'].includes(s.kind))throw Error('Invalid comparison location or income type.');const b=blank();for(const key of Object.keys(b))if(Object.hasOwn(s,key)&&['string','number'].includes(typeof s[key]))b[key]=s[key];if(!['employer','included','separate'].includes(b.professionalMode))throw Error('Invalid cost arrangement.');if(v.version===4&&s.plan&&typeof s.plan==='object'){for(const k of Object.keys(b.plan))if(Object.hasOwn(s.plan,k)&&['string','number'].includes(typeof s.plan[k]))b.plan[k]=s.plan[k];}b.incomeMode=v.version>=3&&b.incomeMode==='benchmark'?'benchmark':'custom';b.benchmarkBasis=['auto','national','state'].includes(b.benchmarkBasis)?b.benchmarkBasis:'auto';b.specialty=B.normalize(b.specialty,b.country);if(b.incomeMode==='benchmark')B.apply(b);syncHealth(b);return b;});
 PL.restore(v.layers);scenarios=next;compareMode=['local','national','budget'].includes(v.compareMode)?v.compareMode:'local';lifestyle=Number.isFinite(v.lifestyle)&&v.lifestyle>=0&&v.lifestyle<=1000000?v.lifestyle:5000;stress=[0,5,10,15,20,25,30].includes(v.stress)?v.stress:15;period=v.period===12?12:1;renderForms();$('file-status').textContent='Comparison loaded.';
 }catch(err){$('file-status').textContent=err.message;}e.target.value='';});
$('evidence-country').addEventListener('change',()=>renderEvidence(true));$('evidence-place').addEventListener('change',()=>renderEvidence());$('evidence-search').addEventListener('input',()=>renderEvidence());
PL.init({get:()=>({scenarios,results:scenarios.map(estimate),lifestyle}),estimate,
 makeScenario:(country,place,specialty,basis)=>{const s={...blank(),country,place,specialty,benchmarkBasis:basis};B.apply(s);applyCosts(s);ensurePrice(s);return s;},
 load:(i,s)=>{scenarios[i]=s;renderForms();}
});
resetPreset('median');renderForms();renderEvidence(true);method();PL.renderExplorer(true);PL.method();
})();
